    appendix('table', 'Những câu hỏi về mô hình và kết quả', headers=['Giảng viên hỏi', 'Trả lời ngắn gọn'], rows=[['POD 0,4 có tốt chưa?', 'Không có chuẩn chung; cần FAR/CSI, ngưỡng, kỳ đo và đối chứng.'], ['L2 sao không thắng dù chấm RMSE?', 'Mẫu hữu hạn, cây hữu hạn; đổi cách học có đánh đổi ngày khô/mưa lớn.'], ['RMSE 2026 thấp hơn 2025 là tiến bộ?', 'Không suy ra vậy: khác tập, mùa, mức mưa và API.'], ['Đã dùng thực tế được chưa?', 'Mới có hồi cứu và tiến trình chờ; cần dự báo trước sự kiện và nhãn đến sau.']], widths=[4.4, 7.7], row_h=0.95, size=19, takeaway='Những kết quả chưa tốt là đầu vào để thiết kế phép kiểm chứng tiếp theo.')
    for keys, title in [(['P1', 'P2', 'P3'], 'Tài liệu gốc về hậu xử lý mưa'), (['P4', 'P5', 'P6'], 'Tài liệu về mục tiêu dự báo và kiến trúc'), (['D1', 'D2', 'D3'], 'Tài liệu chính thức về nguồn và đối chứng')]:
        appendix('references', title, keys=keys, refs=keys, takeaway='Ưu tiên nguồn gốc; phân biệt tạp chí bình duyệt, preprint và tài liệu kỹ thuật.')
    for i, s in enumerate(slides, 1):
        s['number'] = i
        s['main_count'] = main_count
    return slides
